@startuml

class SensorController {
  + username : string
  + password : string
}

class Apartment {
  + address : string
}

class Inhabitant {
  + username : string
  + password : string
  + hasAdminRights : boolean
}

class Room {
  + description : string
}

class Sensor {
  + vendorId : string
  + description : string
  + unit : Unit
  + threshold : float
}

abstract class TemperatureSensor extends Sensor {
  + minValue : float
  + maxValue : float
}

class PowerSensor extends Sensor {
  + counterReading : float
}

enum Unit {
  CELSIUS
  WATT
}

class MeasuredValue {
  + timestamp : datetime
  + value : float
}

class EMonitor {}

class EmailAddress {
  + address : string
}

SensorController "1" *-- "1" Apartment
Apartment "1" *-- "1..*" Room
Apartment "1" o-- "*" Inhabitant
Inhabitant "1" --> "*" Sensor : configures
Room "1" *-- "*" Sensor
Sensor "1" *-- "*" MeasuredValue
Sensor "1" o-- "0..1" MeasuredValue : lastValue
Apartment "1" o-- "0..1" EmailAddress
EMonitor "1" --> "1" SensorController : checks

@enduml

